def reach(seedcells, conn):
    seen=set(seedcells); q=deque(seedcells)
    while q:
        a,b=q.popleft()
        for da,db in conn:
            na,nb=a+da,b+db
            if 0<=na<R_ and 0<=nb<C_ and inp[na][nb]==0 and (na,nb) not in seen:
                seen.add((na,nb)); q.append((na,nb))
    return seen
